await ready('#pilotNewWorkspace');await open('#uiDataTools');
await p.locator('#pilotS4BackupFile').setInputFiles('/tmp/pr46-cont/attempt-02/downloads/independent-S4-full.zip');
const response=p.waitForResponse(r=>r.request().method()==='POST'&&r.url().endsWith('/api/backups/full/restore'));
await (await ready('#pilotS4RestoreFull')).click();await check('SETUP empty isolated restore actual200',(await response).status(),200);
global.seed=JSON.parse(fs.readFileSync('/tmp/pr46-cont/attempt-02/evidence/W04-before-backup.json'));
global.wid=seed.tables.app_state.rows.find(x=>x[0]==='active_workspace')[1];
await p.waitForFunction(id=>window.SRMPilot?.snapshot()?.workspaceId===id,wid);await saved();
await check('SETUP every original fictional DB row/history/PDF byte unchanged',db('SETUP-restored'),seed);
global.ids=(await snap()).state.items.map(x=>x.lineId);await nav('quotes');
await check('P2 initial independent three manual identities',(await snap()).state.manualAwards,[ids[1],ids[4],ids[11]]);
global.baseline=await snap();await expect(p.locator('#srmUxManualAwardSummary')).toContainText('¥1979.00');
await expect(p.locator('#srmUxManualAwardSummary')).toContainText('3 项');
const text=await p.locator('#quoteAnalysis').innerText();await check('P2 distinct theoretical6940 and mixed7064',text.includes('逐物料理论最低价组合：¥6940.00')&&text.includes('当前建议/已选组合：¥7064.00'),true);
await p.locator('#srmUxManualAwardSummary').scrollIntoViewIfNeeded();await shot('P2-3-manual-1979-theory6940-mixed7064');
fs.writeFileSync(root+'baseline-workspace.json',JSON.stringify(baseline,null,2));
log('case-complete',{id:'P2-01',status:'PASS',basis:'actual prior fictional S4 restored through new product UI, current computation and state independently verified'});

await saved();global.exportBefore=db('P2-before-exports');await download('independent-common-scope.csv',p.locator('#exportSelectedCommonScope'));
await open('#uiDataTools');if(!await p.locator('#pilotReportPanel').isVisible())await p.locator('#pilotReportOpen').click();
await p.locator('#pilotReportType').selectOption('rfq');for(const sid of ['U46-A','U46-B','U46-C']){await p.locator('#pilotReportSupplier').selectOption(sid);await download('supplier-'+sid+'.zip',p.locator('#pilotReportDownload'))}
await download('all-suppliers.zip',p.locator('#pilotReportDownloadAll'));await p.locator('#pilotReportType').selectOption('comparison');
for(const box of await p.locator('[data-report-supplier]').all())await box.uncheck();for(const sid of ['U46-A','U46-B'])await p.locator('[data-report-supplier="'+sid+'"]').check();
await download('comparison.xlsx',p.locator('#pilotReportDownload'));fs.writeFileSync(root+'final-workspace.json',JSON.stringify(await snap(),null,2));
cp.execFileSync('python',['/tmp/pr46-retest/methods/verify-exports.py'],{stdio:['ignore',fs.openSync(root+'export-validation.log','w'),fs.openSync(root+'export-validation.stderr','w')]});
await check('P2 exports do not change any database/history/PDF',db('P2-after-exports'),exportBefore);log('case-complete',{id:'P2-02',status:'PASS'});await close('#uiDataTools');

await nav('quotes');await p.locator('#resetAwards').click();await check('P2 reset leaves zero manual identities',(await snap()).state.manualAwards,[]);
await expect(p.locator('#srmUxManualAwardSummary')).toContainText('尚无人工确认的有效定标（0 项');
await check('P2 no manual misleading zero priced award',!(await p.locator('#srmUxManualAwardSummary').innerText()).includes('¥0.00'),true);
await saved();await p.locator('#srmUxManualAwardSummary').scrollIntoViewIfNeeded();await shot('P2-zero-after-reset');
await p.locator('[data-award="'+ids[4]+'|U46-B"]').click();await p.locator('[data-award="'+ids[1]+'|U46-B"]').click();
await expect(p.locator('#awardReasonModal')).toHaveAttribute('aria-hidden','false');await p.locator('#awardReasonInput').fill('完全虚构46：乙方交期与保障更适合本询价');await p.locator('#awardReasonConfirm').click();
await p.locator('#quotePager [data-pg="1"]').click();await p.locator('[data-award="'+ids[11]+'|U46-A"]').click();
await expect(p.locator('#srmUxManualAwardSummary')).toContainText('¥1979.00');await expect(p.locator('#srmUxManualAwardSummary')).toContainText('3 项');await saved();
await p.reload();await saved();await nav('quotes');await expect(p.locator('#srmUxManualAwardSummary')).toContainText('¥1979.00');
await check('P2 reselected persisted three manuals',(await snap()).state.manualAwards,[ids[1],ids[4],ids[11]]);log('case-complete',{id:'P2-03',status:'PASS'});

global.historyBefore=(await snap()).state.quoteRounds;await nav('quoteImport');await p.locator('#quoteImportSupplier').selectOption('U46-B');
await (await ready('#newQuoteRevision')).click();await p.locator('[data-srm-ux-input-mode="paste"]').click();
await p.locator('#quotePaste').fill('RFQ Line ID,报价单价,交期,MOQ,报价状态\n'+ids[1]+',83,9,1,正常报价');await p.locator('#quoteParsePaste').click();
await expect(p.locator('#quoteImportPreviewBody tr')).toHaveCount(1);await (await ready('#commitQuoteImport')).click();await (await ready('#confirmQuoteRound')).click();await saved();await nav('quotes');
await check('P2 new higher quote makes only selected L2 pending review',(await snap()).state.awardReviewIds,[ids[1]]);
await expect(p.locator('#srmUxManualAwardSummary')).toContainText('¥1815.00');await expect(p.locator('#srmUxManualAwardSummary')).toContainText('2 项');
await check('P2 confirmed prior quotes immutable',(await snap()).state.quoteRounds.slice(0,historyBefore.length),historyBefore);
await p.locator('#srmUxManualAwardSummary').scrollIntoViewIfNeeded();await shot('P2-excludes-pending-review-1815-2-lines');
await p.reload();await saved();await nav('quotes');await expect(p.locator('#srmUxManualAwardSummary')).toContainText('¥1815.00');log('case-complete',{id:'P2-04',status:'PASS'});

await open('#uiProjectDetails');await (await ready('#pilotNewWorkspace')).click();await saved();global.scratchId=(await snap()).workspaceId;
await nav('items');if(!await p.locator('#itemIntake').isVisible())await p.locator('#toggleItemIntake').click();
await p.locator('#importFile').setInputFiles('/tmp/pr46-retest/fixtures/independent-items.xlsx');await ready('#confirmImportRows');await expect(p.locator('#importPreview tbody tr')).toHaveCount(12);await p.locator('#confirmImportRows').click();await saved();await nav('quotes');
await check('P2 real twelve materials without valid quotation',(await snap()).state.items.length===12&&(await snap()).state.quoteRounds.length===0,true);
await expect(p.locator('#srmUxManualAwardSummary')).toContainText('尚无人工确认的有效定标（0 项');
await check('P2 no-bid manual aggregate never claims priced zero',!(await p.locator('#srmUxManualAwardSummary').innerText()).includes('¥0.00'),true);
await p.locator('#srmUxManualAwardSummary').scrollIntoViewIfNeeded();await shot('P2-no-effective-quotation-zero-manual');log('case-complete',{id:'P2-05',status:'PASS'});

global.sizes=[[1024,768],[1366,768],[1600,900]];
global.inspectStatus=async(name)=>{await close('#srmUxStatusDetails');await close('#uiProjectDetails');await p.evaluate(()=>window.scrollTo(0,0));
 const actual=await p.evaluate(()=>{const ids=['srmUxWorkspaceSaveSummary','srmV2LiveStatus','pilotSaveStatus','pilotAutosaveStatus','pilotAutoBackupStatus'];return ids.map(id=>{const e=document.getElementById(id);return{id,exists:!!e,visible:!!e&&e.checkVisibility({checkOpacity:true,checkVisibilityCSS:true}),text:e?.textContent,rect:e?{x:e.getBoundingClientRect().x,y:e.getBoundingClientRect().y,width:e.getBoundingClientRect().width,height:e.getBoundingClientRect().height}:null}})});
 log('status-evidence',{name,width:(await p.viewportSize()).width,actual});await check(name+' exactly one visible mounted save/status node',actual.filter(x=>x.visible).map(x=>x.id),['srmUxWorkspaceSaveSummary']);await check(name+' legacy header mirror absent',await p.locator('#srmV2LiveStatus').count(),0);await shot(name);
};
for(const[width,height]of sizes){await p.setViewportSize({width,height});await saved();for(const tab of ['items','assign','quoteImport','quotes','settings']){await nav(tab);await inspectStatus('P3-saved-'+width+'-'+tab);await check('P3 saved summary truthful '+width+' '+tab,await p.locator('#srmUxWorkspaceSaveSummary').innerText(),'已保存');}
 await open('#uiProjectDetails');await open('#srmUxStatusDetails');for(const id of ['pilotSaveStatus','pilotAutosaveStatus','pilotAutoBackupStatus'])await expect(p.locator('#'+id)).toBeVisible();
 await check('P3 original version diagnostics retained '+width,(await p.locator('#pilotAutosaveStatus').innerText()).includes('版'),true);await p.locator('#srmUxStatusDetails').scrollIntoViewIfNeeded();await shot('P3-saved-diagnostics-'+width);await close('#srmUxStatusDetails');await close('#uiProjectDetails');}
log('case-complete',{id:'P3-01',status:'PASS'});

await p.setViewportSize({width:1366,height:768});await nav('items');await saved();global.pendingBefore=db('P3-before-held-request');global.heldRoute=null;
await p.route('**/api/workspaces/**',async route=>{if(route.request().method()==='PUT'&&!heldRoute){global.heldRoute=route;log('intentional-network-latency',{url:route.request().url(),method:'PUT',postData:route.request().postDataJSON()});return;}await route.continue()});
await open('#uiSupplierTools');await p.locator('#pilotCounterpartyCode').fill('CP-RETEST-HELD');await p.locator('#pilotSupplierName').fill('虚构复验等待真实保存供应商');await (await ready('#pilotAddSupplier')).click();
await expect.poll(()=>!!heldRoute,{timeout:20000}).toBe(true);await close('#uiSupplierTools');
await check('P3 genuine pending memory differs from SQLite',JSON.stringify((await snap()).state)!==JSON.stringify((await(await p.request.get(base+'/api/workspaces/'+scratchId)).json()).workspace.state),true);
for(const[width,height]of sizes){await p.setViewportSize({width,height});await inspectStatus('P3-pending-'+width);await check('P3 no false saved during actual held request '+width,(await p.locator('#srmUxWorkspaceSaveSummary').innerText())!=='已保存',true);await check('P3 actual pending indicator '+width,await p.locator('#srmUxWorkspaceSaveSummary').getAttribute('data-srm-ux-save'),'pending');await open('#uiProjectDetails');await open('#srmUxStatusDetails');await expect(p.locator('#pilotAutosaveStatus')).toContainText('保存');await p.locator('#srmUxStatusDetails').scrollIntoViewIfNeeded();await shot('P3-pending-diagnostics-'+width);await close('#srmUxStatusDetails');await close('#uiProjectDetails');}
await check('P3 request hold changes no DB/history/assets',db('P3-while-request-held'),pendingBefore);
await heldRoute.continue();await p.unroute('**/api/workspaces/**');await saved();await check('P3 actual successful persisted supplier',(await(await p.request.get(base+'/api/workspaces/'+scratchId)).json()).workspace.state.suppliers.some(x=>x.id==='CP-RETEST-HELD'),true);
log('case-complete',{id:'P3-02',status:'PASS',note:'Real pending PUT held then continued without fake response; exact database unchanged before release and genuine200 persisted afterward'});

await saved();global.stale=await context.newPage();bind(stale);await stale.goto(base);await saved(stale);const staleRevision=(await snap(stale)).revision;
await open('#uiSupplierTools');await p.locator('#pilotCounterpartyCode').fill('CP-RETEST-WINNER');await p.locator('#pilotSupplierName').fill('虚构复验先保存供应商');await (await ready('#pilotAddSupplier')).click();await saved();global.winner=await snap();await check('P3 actual winner advances version',winner.revision>staleRevision,true);
global.winnerDB=db('P3-before-stale-conflict');await open('#uiSupplierTools',stale);await stale.locator('#pilotCounterpartyCode').fill('CP-RETEST-STALE');await stale.locator('#pilotSupplierName').fill('虚构复验旧标签未保存供应商');
const conflict=stale.waitForResponse(r=>r.request().method()==='PUT'&&r.url().includes('/api/workspaces/'));await (await ready('#pilotAddSupplier',stale)).click();const response=await conflict;
await check('P3 actual SQLite stale request409',response.status(),409);fs.writeFileSync(root+'P3-conflict-http.json',JSON.stringify({status:response.status(),body:await response.json(),staleRevision,winnerRevision:winner.revision},null,2));
await expect(stale.locator('#pilotAutosaveStatus')).toContainText('停止自动重试');await expect(stale.locator('#pilotAutosaveStatus')).toContainText('HTTP 409');
global.primary=p;global.p=stale;await close('#uiSupplierTools');
for(const[width,height]of sizes){await p.setViewportSize({width,height});await inspectStatus('P3-conflict-'+width);await check('P3 accurate concise conflict '+width,await p.locator('#srmUxWorkspaceSaveSummary').innerText(),'保存异常 · 查看详情');await check('P3 actual error indicator '+width,await p.locator('#srmUxWorkspaceSaveSummary').getAttribute('data-srm-ux-save'),'error');await open('#uiProjectDetails');await open('#srmUxStatusDetails');await expect(p.locator('#pilotSaveStatus')).toContainText('未保存成功');await p.locator('#srmUxStatusDetails').scrollIntoViewIfNeeded();await shot('P3-conflict-diagnostics-'+width);await close('#srmUxStatusDetails');await close('#uiProjectDetails');}
await check('P3 rejected stale update preserves every winner DB row/history/PDF byte',db('P3-after-stale-conflict'),winnerDB);await check('P3 stale unsaved data still held in memory',(await snap()).state.suppliers.some(x=>x.id==='CP-RETEST-STALE'),true);
await check('P3 stale record not secretly acknowledged',(await(await p.request.get(base+'/api/workspaces/'+scratchId)).json()).workspace,winner);
await p.close();global.p=primary;await p.reload();await saved();await check('P3 winner survived actual reload',(await snap()).state,winner.state);log('case-complete',{id:'P3-03',status:'PASS',note:'Real two-tab SQLite revision conflict409, no fake network response, unsaved stale state retained and never acknowledged'});
